-- Explicit schema prerequisites for the Hermes release. No existing rows are changed.
-- Matches the canonical JPA entities; PostgreSQL migrations are release-managed.
create table if not exists manual_run_receipt (deleted boolean not null, distance_meters integer, elapsed_seconds integer, activity_id bigint, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, runner_id bigint not null, started_at timestamp(6) with time zone, client_key varchar(36) not null, request_hash varchar(64) not null, time_zone varchar(64), name varchar(120), primary key (id), constraint uk_manual_run_owner_key unique (runner_id, client_key));
create table if not exists runner_plan_profile (baseline_runs_per_week integer not null, can_walk_20_minutes boolean not null, longest_run_m integer not null, result_date date, result_distance_m integer, result_seconds integer, weekly_distance_m integer not null, created_at timestamp(6) with time zone not null, revision bigint not null, runner_id bigint not null, units varchar(8) not null, updated_at timestamp(6) with time zone not null, ability varchar(16) not null, id uuid not null, time_zone varchar(64) not null, primary key (id), unique (runner_id));
create table if not exists training_activity_link (activity_id bigint not null, created_at timestamp(6) with time zone not null, runner_id bigint not null, updated_at timestamp(6) with time zone not null, decision varchar(16) not null, id uuid not null, workout_id uuid not null, primary key (id), unique (activity_id), unique (workout_id));
create table if not exists training_command_receipt (response_status integer not null, created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, runner_id bigint not null, updated_at timestamp(6) with time zone not null, client_key uuid not null, id uuid not null, operation varchar(40) not null, request_hash char(64) not null, result jsonb not null, primary key (id), unique (runner_id, operation, client_key));
create table if not exists training_plan (target_distance_m integer not null, created_at timestamp(6) with time zone not null, revision bigint not null, runner_id bigint not null, updated_at timestamp(6) with time zone not null, goal_kind varchar(16) not null, id uuid not null, state varchar(16) not null, title varchar(120) not null, input_snapshot jsonb not null, primary key (id));
create table if not exists training_plan_version (end_date date not null, generation_local_date date not null, ordinal integer not null, schema_version integer not null, start_date date not null, base_revision bigint not null, created_at timestamp(6) with time zone not null, runner_id bigint not null, updated_at timestamp(6) with time zone not null, id uuid not null, mode varchar(16) not null, plan_id uuid not null, state varchar(16) not null, content_hash char(64) not null, input_hash char(64) not null, retained_hash char(64) not null, time_zone varchar(64) not null, generator_version varchar(80) not null, input_snapshot jsonb not null, warnings jsonb not null, workout_snapshot jsonb not null, primary key (id), unique (plan_id, ordinal));
create table if not exists training_workout (local_date date not null, target_distance_m integer, target_duration_s integer, created_at timestamp(6) with time zone not null, revision bigint not null, runner_id bigint not null, updated_at timestamp(6) with time zone not null, completion_source varchar(16) not null, id uuid not null, phase varchar(16) not null, plan_id uuid not null, state varchar(16) not null, version_id uuid not null, workout_type varchar(16) not null, explanation jsonb not null, primary key (id));
create table if not exists training_workout_step (distance_m integer, duration_s integer, pace_max_s_per_km integer, pace_min_s_per_km integer, repetitions integer not null, sequence integer not null, created_at timestamp(6) with time zone not null, runner_id bigint not null, updated_at timestamp(6) with time zone not null, id uuid not null, step_type varchar(16) not null, workout_id uuid not null, effort_key varchar(80) not null, effort_params jsonb not null, primary key (id), unique (workout_id, sequence));
create index if not exists idx_manual_run_activity on manual_run_receipt (activity_id);
create index if not exists IDX1q62oodhguogmq22vb0d63q6i on training_plan (runner_id, state);
create index if not exists IDX6wcwkdbjjkuw5w506ar1i2f9n on training_workout (runner_id, plan_id, local_date);
